                <th>Listings from Hosts with 5+ Listings</th>
                <th>Professional Host Share</th>
                <th>Interpretation</th>
            </tr>
        </thead>
        <tbody>
            <tr><td><strong>Bangkok</strong></td><td>4,961</td><td>2,998</td><td class="price-high">60.4%</td><td>Highly commercialized</td></tr>
            <tr><td><strong>Barcelona</strong></td><td>3,269</td><td>1,906</td><td class="price-high">58.3%</td><td>Mature institutional market</td></tr>
            <tr><td><strong>Sydney</strong></td><td>3,013</td><td>1,275</td><td>42.3%</td><td>Moderate professional presence</td></tr>
            <tr><td><strong>London</strong></td><td>16,674</td><td>5,363</td><td>32.2%</td><td>Mixed market</td></tr>
            <tr><td><strong>Rome</strong></td><td>6,386</td><td>1,976</td><td>30.9%</td><td>Individual host dominant</td></tr>
            <tr><td><strong>Paris</strong></td><td>13,927</td><td>2,983</td><td>21.4%</td><td>Individual host prevalent</td></tr>
            <tr><td><strong>Amsterdam</strong></td><td>1,770</td><td>120</td><td class="price-mid">6.8%</td><td>Individual host dominated</td></tr>
