        <canvas id="demandChart"></canvas>
    </div>

    <table>
        <thead>
            <tr>
                <th>City</th>
                <th>Avg Reviews/Month</th>
                <th>Total Reviews</th>
                <th>LTM Reviews</th>
                <th>Demand Signal</th>
            </tr>
        </thead>
        <tbody>
            <tr><td><strong>Rome</strong></td><td>1.77</td><td>382,872</td><td>91,651</td><td>Very High</td></tr>
            <tr><td><strong>Barcelona</strong></td><td>1.43</td><td>165,058</td><td>34,532</td><td>High</td></tr>
            <tr><td><strong>Sydney</strong></td><td>1.44</td><td>116,207</td><td>33,547</td><td>High</td></tr>
            <tr><td><strong>Amsterdam</strong></td><td>1.02</td><td>83,244</td><td>15,358</td><td>Moderate</td></tr>
            <tr><td><strong>Paris</strong></td><td>1.01</td><td>380,080</td><td>94,888</td><td>Moderate</td></tr>
            <tr><td><strong>London</strong></td><td>0.99</td><td>369,544</td><td>96,392</td><td>Moderate</td></tr>
            <tr><td><strong>Bangkok</strong></td><td>0.96</td><td>97,148</td><td>28,367</td><td>Moderate</td></tr>
        </tbody>
    </table>

