            <tr><td><strong>Rome</strong></td><td>219 days</td><td>5.4</td><td>637 (10.0%)</td><td>Seasonal focus</td></tr>
            <tr><td><strong>Barcelona</strong></td><td>194 days</td><td>15.5</td><td>1,259 (38.5%)</td><td>Regulatory constraints</td></tr>
